<script lang="ts">
  import { CATALOG, CATALOG_VERSION, CATALOG_STATUS, evaluateWorkspace, createAction, closeAction, addDecision, reviewNeeded, type Finding, type Workspace } from "@rgpdesk/privacy-core";
  import Icon from "./Icon.svelte";
  let { workspace, busy, onSave }: { workspace: Workspace; busy: boolean; onSave: (next: Workspace) => Promise<void> } = $props();
  let scope = $state(""); let ownerFilter = $state(""); let dueFilter = $state(""); let ruleFilter = $state("");
  let selected: Finding | null = $state(null); let owner = $state(""); let due = $state(""); let closing = $state(""); let author = $state(""); let justification = $state("");
  let showDecision = $state(false); let decisionRule = $state("R-009"); let decisionActivity = $state(""); let conclusion = $state("");
  const now = () => new Date().toISOString();
  let findings = $derived(evaluateWorkspace(workspace, now().slice(0, 10)));
  let visible = $derived(findings.filter((f) => (!scope || f.activityId === scope) && (!ruleFilter || f.ruleId === ruleFilter)));
  let actions = $derived(workspace.actions.filter((a) => (!scope || a.activityId === scope) && (!ownerFilter || a.owner.toLocaleLowerCase().includes(ownerFilter.toLocaleLowerCase())) && (!dueFilter || a.due !== null && a.due <= dueFilter)));
</script>
<section class="panel">
  <div class="section-heading"><div><p class="eyebrow">Suivi documentaire</p><h2>Chaque question trouve sa suite.</h2></div><span class="icon-tile"><Icon name="actions" size={26} /></span></div>
  <p class="help">{CATALOG_STATUS}. Les constats restent des questions à examiner. Une action close n’efface ni le constat ni son historique.</p>
  <div class="filters"><label class="field">Périmètre<select aria-label="Périmètre" bind:value={scope}><option value="">Toutes les activités</option>{#each workspace.activities as a}<option value={a.id}>{a.title}</option>{/each}</select></label><label class="field">Information manquante<select aria-label="Information manquante" bind:value={ruleFilter}><option value="">Tous les contrôles</option>{#each CATALOG.filter((r) => r.id !== "R-010") as r}<option value={r.id}>{r.title}</option>{/each}</select></label></div>
  <h3>Questions ouvertes <span class="count">{visible.length}</span></h3>
  <ul class="finding-list">{#each visible as f (f.key)}<li><span class="finding-marker"><Icon name="eye" size={18} /></span><div class="grow"><strong>{CATALOG.find((r) => r.id === f.ruleId)?.title}</strong><p>{workspace.activities.find((a) => a.id === f.activityId)?.title ?? "Organisation"} · {f.message}</p></div>{#if workspace.actions.some((a) => a.findingKey === f.key)}<span class="tag">Action déjà suivie</span>{:else}<button class="secondary" disabled={busy} onclick={() => { selected = f; owner = ""; due = ""; }}>Créer une action</button>{/if}</li>{/each}</ul>
  {#if selected}<form class="subpanel" onsubmit={(e) => { e.preventDefault(); if (selected) void onSave(createAction(workspace, selected, { id: crypto.randomUUID(), owner, due: due || null }, now())); }}><fieldset disabled={busy}><h3>Nouvelle action · {CATALOG.find((r) => r.id === selected!.ruleId)?.title}</h3><div class="grid-two"><label class="field">Responsable de l’action<input required maxlength="160" bind:value={owner} /></label><label class="field">Échéance déclarée<input type="date" bind:value={due} /></label></div><button type="submit">Enregistrer l’action</button><button type="button" class="secondary" onclick={() => selected = null}>Annuler l’action</button></fieldset></form>{/if}
  <div class="section-heading"><h3>Plan d’actions</h3><span class="tag">{workspace.actions.filter((a) => !a.closure).length} en cours</span></div>
  <div class="filters"><label class="field">Filtrer par responsable<input maxlength="160" bind:value={ownerFilter} placeholder="Responsable de l’action" /></label><label class="field">Échéance au plus tard<input type="date" bind:value={dueFilter} /></label></div>
  <ul class="records">{#each actions as a}<li><span class="record-icon"><Icon name={a.closure ? "check" : "clock"} /></span><div class="grow"><strong>{CATALOG.find((r) => r.id === a.ruleId)?.title} · {a.scope}</strong><p>{a.owner} · {a.due ?? "Sans échéance"} · {a.closure ? "Clôture déclarée" : "En cours"}{reviewNeeded(a, workspace) ? " · Revue à refaire (révision ou catalogue)" : ""}</p>{#if a.closure}<p>{a.closure.at} · {a.closure.author} : {a.closure.justification}</p>{/if}</div>{#if !a.closure}<button class="secondary" disabled={busy} onclick={() => { closing = a.id; author = ""; justification = ""; }}>Clôturer</button>{/if}</li>{/each}</ul>
  {#if closing}<form class="subpanel" onsubmit={(e) => { e.preventDefault(); void onSave(closeAction(workspace, closing, author, justification, now())); }}><fieldset disabled={busy}><h3>Conserver la justification de clôture</h3><label class="field">Auteur déclaré de la clôture<input required maxlength="160" bind:value={author} /></label><label class="field">Justification de clôture<textarea required maxlength="4000" bind:value={justification}></textarea></label><p class="help">Cette déclaration ne prouve pas l’exécution dans vos systèmes. La clôture sera conservée sans réécriture.</p><button>Enregistrer la clôture</button><button type="button" class="secondary" onclick={() => closing = ""}>Annuler la clôture</button></fieldset></form>{/if}
  <div class="section-heading"><h3>Décisions motivées</h3><button class="secondary" disabled={busy} onclick={() => { showDecision = !showDecision; author = ""; justification = ""; conclusion = ""; }}>Documenter une décision</button></div>
  {#if showDecision}<form class="subpanel" onsubmit={(e) => { e.preventDefault(); void onSave(addDecision(workspace, { id: crypto.randomUUID(), ruleId: decisionRule, activityId: decisionActivity || null, author, justification, conclusion }, now())); }}><fieldset disabled={busy}>
    <div class="grid-two"><label class="field">Question examinée<select aria-label="Question examinée" bind:value={decisionRule}>{#each CATALOG.filter((r) => r.id !== "R-010") as r}<option value={r.id}>{r.title}</option>{/each}</select></label><label class="field">Périmètre de la décision<select aria-label="Périmètre de la décision" bind:value={decisionActivity}><option value="">Organisation</option>{#each workspace.activities as a}<option value={a.id}>{a.title}</option>{/each}</select></label></div>
    <label class="field">Auteur déclaré de la décision<input required maxlength="160" bind:value={author} /></label><label class="field">Décision déclarée<textarea required maxlength="4000" bind:value={conclusion}></textarea></label><label class="field">Motivation de la décision<textarea required maxlength="4000" bind:value={justification}></textarea></label><button>Conserver la décision</button>
  </fieldset></form>{/if}
  {#each workspace.decisions as d}<article class="subpanel"><span class="tag">{reviewNeeded(d, workspace) ? "À réexaminer" : "Déclaration sur cette révision"}</span><h4>{d.conclusion}</h4><p>{d.justification}</p><small>{d.author} · {d.createdAt} · révision {d.revision} · {d.catalogVersion}</small></article>{/each}
  <details class="subpanel"><summary>Comprendre les contrôles & leurs sources · {CATALOG_VERSION}</summary><p class="help">Traductions proposées en contrôles produit. Consultation des textes : 22 septembre 2026. Aucune revue humaine attribuée. Un changement du dossier ou du catalogue demande un nouvel examen, sans modifier les décisions passées.</p>{#each CATALOG as rule}<article><h4>{rule.id} · {rule.title}</h4><p>{rule.explanation}</p><p class="help">Faits : {rule.facts}. Version {rule.version} · {rule.jurisdiction} · Statut : non revu · Nature du contrôle : pratique produit.</p><a href={rule.source} target="_blank" rel="noreferrer noopener">Source CNIL · articles {rule.article}</a></article>{/each}</details>
</section>
